using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.VTS.LogUsoVisitas;using GraphApi.Services.VTS.LogUsoVisitas;namespace GraphApi.Controllers.VTS.LogUsoVisitas{    /// <summary>    /// Gestión de LogUsoVisitas: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("VTS/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre LogUsoVisitas")]    public class LogUsoVisitasController : Controller    {        private readonly ILogUsoVisitasService _objService;        public LogUsoVisitasController(ILogUsoVisitasService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los LogUsoVisitas, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="logUsoVisitaID">LogUsoVisitaID</param>        /// <param name="visitaGeneradaID">VisitaGeneradaID</param>        /// <param name="fechaAcceso">FechaAcceso</param>        /// <param name="iPOrigen">IPOrigen</param>        /// <param name="userAgent">UserAgent</param>        /// <param name="exitoso">Exitoso</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de LogUsoVisitas</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar LogUsoVisitas",            Description = "Devuelve LogUsoVisitas aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadLogUsoVisitas>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadLogUsoVisitas>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? logUsoVisitaID,            [FromQuery] int? visitaGeneradaID,            [FromQuery] DateTime? fechaAcceso,            [FromQuery] string? iPOrigen,            [FromQuery] string? userAgent,            [FromQuery] bool? exitoso,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetLogUsoVisitasDynamic(                logUsoVisitaID,                 visitaGeneradaID,                 fechaAcceso,                 iPOrigen,                 userAgent,                 exitoso,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo LogUsoVisita.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del LogUsoVisita a crear.</param>        /// <returns>El LogUsoVisita recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear LogUsoVisitas",            Description = "Inserta un nuevo LogUsoVisita en la base de datos."        )]        [ProducesResponseType(typeof(clReadLogUsoVisitas), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadLogUsoVisitas>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateLogUsoVisitas objInput)        {            var vCreated = await _objService.CreateLogUsoVisitas(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de LogUsoVisita.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del LogUsoVisita.</param>        /// <returns>El LogUsoVisita actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar LogUsoVisitas",            Description = "Actualiza uno o varios campos de LogUsoVisita existente."        )]        [ProducesResponseType(typeof(clReadLogUsoVisitas), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadLogUsoVisitas>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateLogUsoVisitas objInput)        {            var vUpdated = await _objService.UpdateLogUsoVisitas(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un LogUsoVisita por su ID.        /// </summary>        [HttpDelete("{nLogUsoVisitasID:int}")]        [SwaggerOperation(            Summary = "Eliminar LogUsoVisita",            Description = "Borra un LogUsoVisita si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nLogUsoVisitasID)        {            var success = await _objService.DeleteLogUsoVisitas(nLogUsoVisitasID);            return success ? NoContent() : NotFound();        }    }}